
'use strict';
const {docs,editorial,assets}=window.ATLAS_DATA;const pdfs={};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)],byId=id=>docs.find(d=>d.id===id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),fmt=n=>new Intl.NumberFormat('pt-BR').format(n),paras=s=>String(s??'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');
const STORAGE='aldenir-atlas-publico-v2';let persistent=true;
const object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
function validateState(p){const s={done:{},notes:'',next:'',font:18,dark:true,card:0,known:{},resume:null};if(!object(p))return s;
 if(typeof p.notes==='string')s.notes=p.notes;if(typeof p.next==='string')s.next=p.next;
 s.font=Math.max(15,Math.min(25,Number(p.font)||18));if(typeof p.dark==='boolean')s.dark=p.dark;
 if(Number.isFinite(p.card))s.card=Math.max(0,Math.floor(p.card))%editorial.flashcards.length;
 if(object(p.done))for(const d of docs)if(p.done[d.id]===true)s.done[d.id]=true;
 if(object(p.known))for(let i=0;i<editorial.flashcards.length;i++)if(p.known[i]===true)s.known[i]=true;
 if(object(p.resume)&&docs.some(d=>d.id===p.resume.id))s.resume={id:p.resume.id,y:Math.max(0,Math.min(1e8,Number(p.resume.y)||0))};return s}
let state=validateState(null);try{state=validateState(JSON.parse(localStorage.getItem(STORAGE)||'null'));localStorage.setItem(STORAGE,JSON.stringify(state))}catch(e){persistent=false}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));persistent=true}catch(e){persistent=false}updateProgress()}
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3500)}
function updateProgress(){const n=docs.filter(d=>d.words>0&&state.done[d.id]).length;$('#progressLabel').textContent=`${n} de 31 documentos estudados`;$('#progressBar').value=n}
function refs(ids=[]){return `<div class="source-links">${[...new Set(ids)].map(id=>{const d=byId(id);return d?`<a class="source-link" href="#obra/${id}" title="${esc(d.title)}">↗ ${id.replace('obra-','')} · ${esc(d.title.slice(0,48))}</a>`:''}).join('')}</div>`}
function badge(t){return `<span class="pill">${esc(t)}</span>`}
function applyPrefs(){document.body.classList.toggle('dark',!!state.dark);document.documentElement.style.setProperty('--reading',Math.max(15,Math.min(25,Number(state.font)||18))+'px')}
const assetURLs=new Map(),pdfURLs=new Map();function blobURL(base64,type){const chars=atob(base64),bytes=new Uint8Array(chars.length);for(let i=0;i<chars.length;i++)bytes[i]=chars.charCodeAt(i);return URL.createObjectURL(new Blob([bytes],{type}))}
function assetURL(id){return assets[id]?.url||''}
function activateImages(root=document){root.querySelectorAll('img[data-asset]').forEach(img=>{const a=assets[img.dataset.asset];if(a){img.src=assetURL(img.dataset.asset);img.width=a.width;img.height=a.height}else img.alt+=' — imagem indisponível'})}
const searchIndex=docs.map(d=>({id:d.id,title:norm(d.title+' '+d.name+' '+d.theme),text:norm(d.text),original:d.text}));let query='',themeFilter='',currentTab='integral',currentBook=null;
function home(){return `<p class="eyebrow">Seu universo, organizado para aprender</p><section class="hero"><div><h1>Ideias que se conectam.<br>Um acervo para estudar.</h1><p class="lede">Phoenix, Piratas do Infinito e Armagedom XXX em diálogo com ética, música e vida cotidiana. Entre pela síntese e avance até cada texto completo.</p><div class="actions"><a class="button primary" href="#trilhas">Começar uma trilha →</a><a class="button" href="#biblioteca">Explorar as obras</a></div><div class="stats"><div><strong>33</strong><span>arquivos incorporados</span></div><div><strong>7</strong><span>módulos de síntese</span></div><div><strong>${fmt(editorial.totalWords)}</strong><span>palavras nas fontes¹</span></div></div></div><div class="hero-art" aria-label="Ética, imaginação e aprendizagem se conectam no acervo"><div class="orbit"></div><div class="orbit second"></div><div class="hero-glyph">Φ<small>conhecer · conectar · praticar</small></div><span class="orbit-label l1">IMAGINAÇÃO</span><span class="orbit-label l2">APRENDIZAGEM</span><span class="orbit-label l3">ÉTICA</span></div></section>
<div class="visual-invitation"><div><h3>Um atlas para aprender pelo olhar</h3><p>12 diagramas novos, 2 ilustrações temáticas e a galeria completa das imagens das obras.</p></div><a class="button primary" href="#visuais">Explorar o atlas visual ↗</a></div><div class="section-head"><h2>Três portas de entrada</h2><span class="small">Escolha apenas uma para começar</span></div><div class="grid"><article class="card"><span class="num">01 / ENTENDER</span><h3>O sentido do conjunto</h3><p>Como a imaginação se torna linguagem para discutir dignidade, autonomia, pertencimento e responsabilidade.</p><a href="#mapa">Ver as conexões →</a></article><article class="card"><span class="num">02 / APROFUNDAR</span><h3>Uma obra por vez</h3><p>Síntese, pontos centrais, pergunta de estudo e texto integral. As versões continuam identificadas.</p><a href="#biblioteca">Abrir a biblioteca →</a></article><article class="card"><span class="num">03 / RECORDAR</span><h3>Transformar leitura em memória</h3><p>Responda antes de revelar, registre o que entendeu e deixe a próxima ação preparada.</p><a href="#revisao">Revisar com cartões →</a></article></div>
${state.resume?`<div class="notice"><strong>Continue de onde parou.</strong> ${esc(byId(state.resume.id)?.title||'Última leitura')}<div class="actions"><button data-resume>Retomar leitura</button></div></div>`:''}
<div class="section-head"><h2>O fio condutor</h2></div><div class="module-body"><p>O acervo usa universos narrativos para pensar como viver, aprender e conviver. <strong>Phoenix</strong> oferece uma arquitetura de reconstrução e organização; <strong>Piratas do Infinito</strong> desenvolve códigos de coragem, mérito e justiça; <strong>Armagedom XXX</strong> e os códigos dos planos exploram os limites entre mundo real, símbolo e ficção. Os guias de música acrescentam escuta, contexto cultural e elaboração de emoções.</p><p>Esta conexão é uma <strong>síntese editorial</strong>, não uma afirmação de que todos os livros usam o mesmo cânone. A biblioteca mantém suas diferenças para que você possa comparar ideias sem perder a origem.</p></div>
<div class="notice"><strong>Como ler com precisão.</strong> Os textos integrais reproduzem o conteúdo documental. As sínteses explicam relações e apontam limites. Magia, Casas e mapas astrais são recursos ficcionais ou simbólicos; referências históricas e clínicas exigem o grau de verificação indicado em cada obra.</div>
<p class="fineprint">¹ Contagem da extração, incluindo versões, tabelas, cabeçalhos e repetição entre arquivos. Esta edição cobre os 33 arquivos do Arquivo.zip enviado. Outras obras ou conversas não presentes no pacote não foram incorporadas. <a href="#edicao">Ver cobertura e critérios da edição.</a></p>`}
function modulesGrid(){return editorial.modules.map((m,i)=>`<article class="card"><span class="num">MÓDULO ${String(i+1).padStart(2,'0')}</span><h3><a href="#modulo/${i}">${esc(m.title)}</a></h3><p>${esc(m.intro)}</p><a href="#modulo/${i}">Estudar este tema →</a></article>`).join('')}
function trails(){return `<p class="eyebrow">Uma etapa de cada vez</p><h1>Trilhas de estudo</h1><p class="lede">Escolha o tempo disponível. O objetivo de cada sessão é sair com uma ideia explicada nas suas palavras.</p><div class="grid"><div class="card"><span class="num">10 MINUTOS</span><h3>Encontre o fio</h3><ol><li>Abra o mapa das ideias.</li><li>Escolha uma conexão e leia sua explicação.</li><li>Responda a um cartão sem consultar.</li></ol><a href="#mapa">Iniciar →</a></div><div class="card"><span class="num">25 MINUTOS</span><h3>Entenda um módulo</h3><ol><li>Leia uma síntese temática.</li><li>Confira um trecho da fonte indicada.</li><li>Registre três ideias e uma dúvida.</li></ol><a href="#modulo/0">Abrir o primeiro módulo →</a></div><div class="card"><span class="num">50 MINUTOS</span><h3>Compare e aplique</h3><ol><li>Escolha duas versões da mesma família.</li><li>Compare regra, finalidade e limite.</li><li>Faça uma pausa; escreva sua conclusão.</li></ol><a href="#edicao">Escolher versões →</a></div></div><div class="section-head"><h2>Sete módulos para compreender o acervo</h2><span class="small">Sínteses novas, com links para os textos de origem</span></div><div class="grid two">${modulesGrid()}</div><div class="notice">As durações são sugestões flexíveis de organização, não prescrições clínicas. Você pode interromper, retomar e adaptar cada sessão.</div><div class="section-head"><h2>Uma sequência possível</h2></div>${[['Fronteira entre realidade e ficção','Comece pelo Código dos Planos para compreender o que pode e o que não pode atravessar da narrativa para a vida.',['obra-08','obra-21']],['Fundação Phoenix','Passe pela iniciação e pelo universo; depois consulte o módulo do Mestre para regras e exemplos mais extensos.',['obra-20','obra-05','obra-04']],['Ética e sociedade','Leia os Piratas e a Conurbação perguntando como as instituições distribuem poder, proteção e responsabilidade.',['obra-07','obra-06','obra-12']],['Música e prática pessoal','Use os guias para escutar com atenção e registre o que é interpretação, contexto histórico e experiência sua.',['obra-19','obra-22','obra-33']]].map((x,i)=>`<div class="trail"><span class="step">${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p>${refs(x[2])}</div></div>`).join('')}`}
const connections=[{title:'Ética e convivência',sub:'Dignidade, limites, justiça',body:'A dignidade aparece como condição básica, enquanto mérito e responsabilidade regulam reconhecimento e consequências. Essa distinção permite estudar uma tensão central: como reconhecer diferenças de contribuição sem converter pessoas em hierarquias de valor humano. Os códigos dos planos acrescentam consentimento e possibilidade de recusa.',question:'Uma recompensa por mérito altera os direitos básicos de alguém? Compare o piso de dignidade com as regras da versão lida.',ids:['obra-07','obra-08','obra-10','obra-28']},{title:'Imaginação e identidade',sub:'Casas, escolas, personagens',body:'Phoenix organiza perfis, papéis e caminhos de desenvolvimento por meio de Casas e Escolas. Armagedom e o mapa astral RPG ampliam a linguagem simbólica. Esses sistemas são regras de construção narrativa: podem ajudar a formular perguntas pessoais, mas não demonstram capacidades sobrenaturais ou um diagnóstico.',question:'A regra que você está lendo descreve um personagem, uma preferência simbólica ou uma afirmação sobre o mundo real?',ids:['obra-01','obra-05','obra-25','obra-26']},{title:'Música e experiência',sub:'História, escuta, elaboração',body:'Os guias de Nirvana e Linkin Park combinam contexto, estrutura sonora e interpretação. A experiência subjetiva do ouvinte é uma camada própria: pode dialogar com a obra sem provar a intenção do artista. Dragon Ball e os Piratas funcionam como pontes literárias para temas como pertencimento e persistência.',question:'O que você ouviu no som, o que aprendeu em uma fonte e o que interpretou pessoalmente?',ids:['obra-18','obra-19','obra-22','obra-31']},{title:'Estudo e ação cotidiana',sub:'Pequenos passos, registro, retorno',body:'Fichas, quests, timers e cadernos transformam intenções amplas em ações observáveis. A metáfora é útil quando produz uma tarefa simples, revisável e compatível com os recursos disponíveis. No acervo, a IA aparece como ferramenta de organização; seu resultado ainda precisa de conferência.',question:'Qual ação concreta, pequena e verificável pode sair desta leitura? O que mostraria que ela foi útil?',ids:['obra-13','obra-16','obra-17','obra-20','obra-33']}];
function mapPage(){return `<p class="eyebrow">Conexões interpretativas</p><h1>O mapa das ideias</h1><p class="lede">Clique em um eixo para enxergar a relação entre as obras. Este mapa é uma leitura editorial do conjunto, não uma fusão das regras.</p><div class="graph"><div class="graph-hub"><strong>UNIVERSO DO ACERVO</strong><br><small>Imaginar · compreender · agir</small></div><div class="graph-nodes">${connections.map((c,i)=>`<button data-connect="${i}" class="${i===0?'selected':''}" aria-pressed="${i===0}"><strong>${c.title}</strong><span>${c.sub}</span></button>`).join('')}</div></div><div id="connectionDetail"></div><div class="section-head"><h2>Uma lente para sociologia e democracia</h2></div><p class="lede">O pacote é majoritariamente literário e reflexivo. As perguntas abaixo conectam seus dilemas ao tema do projeto, sem pressupor que ele contenha um tratado sistemático de sociologia.</p><div class="grid two">${[['Poder e consentimento','Quem pode decidir, quem pode recusar e como uma decisão pode ser contestada? Observe as regras sobre livre-arbítrio e autoridade.'],['Dignidade e desigualdade','Quais garantias pertencem a todos? Quais recompensas dependem de mérito? Teste se a regra cria privilégios permanentes.'],['Instituições e responsabilidade','Quem fiscaliza os líderes e corrige um erro? Uma ordem narrativa tem regras públicas e critérios de revisão?'],['Mito e evidência','Uma história ajuda a compreender valores, mas o que seria necessário para sustentar uma afirmação sobre grupos e acontecimentos reais?']].map(x=>`<div class="card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div><div class="section-head"><h2>Quatro camadas de leitura</h2></div><div class="table-scroll"><table><tr><th>Camada</th><th>Pergunta orientadora</th><th>Exemplo do acervo</th></tr><tr><td>Ficção</td><td>O que vale dentro deste universo e desta versão?</td><td>Escolas, magia, patentes e portais.</td></tr><tr><td>Símbolo</td><td>Que significado pessoal ou moral está sendo proposto?</td><td>Reconstrução Phoenix e coragem pirata.</td></tr><tr><td>Afirmação factual</td><td>Qual fonte sustenta a afirmação e quando ela foi verificada?</td><td>História de bandas, instituições e calendários.</td></tr><tr><td>Aplicação cotidiana</td><td>Qual ação real é viável, consentida e avaliável?</td><td>Uma ficha de estudo ou um registro de escuta.</td></tr></table></div>`}
function connection(i){const c=connections[i];$('#connectionDetail').innerHTML=`<article class="card"><span class="eyebrow">${c.sub}</span><h2>${c.title}</h2><p style="font-size:17px">${c.body}</p><p><strong>Para pensar:</strong> ${c.question}</p>${refs(c.ids)}</article>`;$$('[data-connect]').forEach(b=>{b.classList.toggle('selected',+b.dataset.connect===i);b.setAttribute('aria-pressed',String(+b.dataset.connect===i))})}
function modulePage(i){const m=editorial.modules[i];if(!m)return '<h1>Módulo não encontrado</h1>';return `<p class="eyebrow">Síntese editorial · módulo ${Number(i)+1} de 7</p><h1>${esc(m.title)}</h1><p class="lede">${esc(m.intro)}</p>${visualModule(i)}<div class="actions no-print"><a class="button" href="#trilhas">← Todas as trilhas</a><button data-print>Imprimir módulo</button><a class="button" href="#caderno">Anotar uma ideia</a></div><article class="module-body">${m.sections.map(s=>`<section><h2>${esc(s.title)}</h2>${paras(s.body)}${refs(s.sources)}</section>`).join('')}</article><div class="notice">Os links de origem abrem as obras preservadas. Esta síntese descreve seus conceitos e limitações; não atribui uma única versão canônica ao conjunto.</div><div class="actions"><a class="button primary" href="#${+i<editorial.modules.length-1?'modulo/'+(+i+1):'revisao'}">${+i<editorial.modules.length-1?'Próximo módulo →':'Ir para revisão →'}</a></div>`}
function library(){return `<p class="eyebrow">33 arquivos · conteúdo incorporado</p><h1>Biblioteca integral</h1><p class="lede">Encontre uma ideia ou escolha uma obra. A busca consulta o texto completo de todas as versões, com ou sem acentos.</p><div class="filters"><label><span class="sr-only">Filtrar por tema</span><select id="themeFilter"><option value="">Todos os temas</option>${[...new Set(docs.map(d=>d.theme))].sort().map(t=>`<option ${t===themeFilter?'selected':''}>${esc(t)}</option>`).join('')}</select></label><button id="clearSearch">Limpar busca e filtros</button></div><p id="resultCount" class="small" role="status"></p><div id="bookResults" class="book-list"></div>`}
function renderResults(){const terms=norm(query.trim()).split(/\s+/).filter(Boolean),results=docs.filter(d=>{const x=searchIndex.find(x=>x.id===d.id);return(!themeFilter||d.theme===themeFilter)&&terms.every(t=>(x.title+' '+x.text).includes(t))});$('#resultCount').textContent=`${results.length} de 33 arquivos${query?' · busca: “'+query+'”':''}`;$('#bookResults').innerHTML=results.map(d=>{let snip='';if(terms.length&&d.text){const t=norm(d.text),pos=t.indexOf(terms.find(w=>t.includes(w))||'');if(pos>=0)snip=`<p class="snip">…${esc(d.text.slice(Math.max(0,pos-80),pos+235))}…</p>`}return `<article class="book"><span class="book-number">${d.id.slice(-2)}</span><div>${badge(d.theme)}${badge(d.ext.slice(1).toUpperCase())}${state.done[d.id]?badge('✓ Estudado'):''}<h3><a href="#obra/${d.id}">${esc(d.title)}</a></h3><p>${esc(d.summary)}</p>${snip}<span class="small">${d.words?fmt(d.words)+' palavras · ':''}${d.nature?esc(d.nature):''}</span></div><a class="button" href="#obra/${d.id}">Abrir obra →</a></article>`}).join('')||'<div class="empty">Nenhum arquivo corresponde à busca. Experimente uma palavra mais curta ou remova o filtro de tema.</div>'}
function docPage(id){const d=byId(id);if(!d)return '<h1>Obra não encontrada</h1>';currentBook=id;return `<header class="doc-header"><p class="eyebrow">Biblioteca de estudo · obra ${id.slice(-2)} de 33</p><h1>${esc(d.title)}</h1><div>${badge(d.theme)}${badge(d.ext.slice(1).toUpperCase())}${badge(d.words?fmt(d.words)+' palavras':'Figura do acervo')}</div><div class="actions no-print"><a class="button" href="#biblioteca">← Biblioteca</a>${d.words?`<button data-done="${id}" aria-pressed="${!!state.done[id]}">${state.done[id]?'✓ Estudado':'Marcar como estudado'}</button>`:''}<button data-print>Imprimir leitura</button>${pdfs[id]?`<button data-pdf="${id}">Ver PDF original</button><button data-downloadpdf="${id}">Salvar PDF original</button>`:''}</div></header><div class="tabs no-print" role="tablist" aria-label="Modo de leitura"><button data-tab="integral" role="tab" aria-selected="${currentTab==='integral'}">Leitura pública</button><button data-tab="sintese" role="tab" aria-selected="${currentTab==='sintese'}">Síntese e estudo</button><button data-tab="fonte" role="tab" aria-selected="${currentTab==='fonte'}">Ficha da fonte</button></div><section id="docContent" role="tabpanel"></section>`}
function docContent(){const d=byId(currentBook);$$('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===currentTab)));if(currentTab==='integral'){$('#docContent').innerHTML=`<p class="small">Conteúdo da fonte preservado · ${d.ext==='.pdf'?'transcrição com PDF original disponível':d.ext==='.png'?'figura incorporada':'diagramação adaptada para leitura'}.</p>${d.limits?`<details class="no-print"><summary>Nota de leitura desta obra</summary><p>${esc(d.limits)}</p></details>`:''}<div class="reading-layout"><article class="reading" id="sourceText">${d.html}</article><aside class="toc no-print" aria-label="Sumário da obra"><strong>Nesta obra</strong>${d.toc.length?d.toc.map(h=>`<a class="${h.level>3?'indent':''}" href="#${h.id}" data-heading="${h.id}">${esc(h.text)}</a>`).join(''):'<p>Use a busca do navegador para localizar um trecho.</p>'}</aside></div>`;activateImages($('#docContent'))}else if(currentTab==='sintese'){$('#docContent').innerHTML=`<article class="module-body"><h2>O que esta obra desenvolve</h2>${paras(d.summary)}<h3>Ideias para guardar</h3><ul>${(d.keypoints||[]).map(p=>`<li>${esc(p)}</li>`).join('')}</ul>${d.studyQuestion?`<details><summary>${esc(d.studyQuestion)}</summary>${paras(d.answer)}</details>`:''}<div class="notice">${esc(d.limits||'A figura é reproduzida como parte do acervo fornecido.')}</div><h3>Leia em conexão</h3>${refs(d.related||[])}</article>`}else{$('#docContent').innerHTML=`<div class="card break-word"><h2>Identificação da fonte</h2><p><strong>Nome no pacote:</strong> ${esc(d.name)}</p><p><strong>Formato:</strong> ${d.ext.toUpperCase()} · <strong>Tamanho original:</strong> ${fmt(d.size)} bytes.</p><p><strong>Data registrada no ZIP:</strong> ${d.date[2]}/${d.date[1]}/${d.date[0]}. A data do pacote não comprova data de autoria nem precedência canônica.</p><p><strong>Conteúdo:</strong> ${fmt(d.words)} palavras extraídas${d.tables?', '+fmt(d.tables)+' tabelas no Word':''}${d.images.length?', '+d.images.length+' imagens internas':''}${d.pages?', '+d.pages+' páginas de PDF':''}.</p><p><strong>Natureza:</strong> ${esc(d.nature||'Material gráfico de apoio')}</p><details><summary>Registro de integridade</summary><p>SHA-256 do arquivo de origem</p><code>${esc(d.sha256)}</code><p>Esse identificador permite comparar o arquivo original com outra cópia.</p></details><p class="small">A apresentação em HTML adapta a diagramação. Numeração automática, quebras de página e elementos de Word podem mudar de aparência. Nos PDFs, o original está incorporado para consulta fiel. No texto integral, cabeçalhos e rodapés aparecem em elementos complementares.</p></div>`}}
function flashPage(){return `<p class="eyebrow">Recuperar antes de reler</p><h1>Revisão ativa</h1><p class="lede">Leia a pergunta, formule sua resposta e só então revele. Os cartões revisam conceitos do acervo e suas distinções.</p><div class="filters"><button data-shuffle>Sortear um cartão</button><button data-review-reset>Recomeçar revisão</button><a class="button" href="#glossario">Consultar glossário</a></div><div id="flashArea"></div><div class="notice">A marca “lembrei” é uma autoavaliação de estudo. Não mede inteligência, habilidade clínica ou perfil cognitivo.</div>`}
function flashRender(){const cards=editorial.flashcards;state.card=((Number(state.card)||0)%cards.length+cards.length)%cards.length;const c=cards[state.card],known=Object.values(state.known||{}).filter(Boolean).length;$('#flashArea').innerHTML=`<p class="small" style="text-align:center">Cartão ${state.card+1} de ${cards.length} · ${known} marcados como lembrados</p><article class="flashcard"><span class="eyebrow">Responda com suas palavras</span><h2>${esc(c.q)}</h2><div class="answer" id="flashAnswer" hidden>${paras(c.a)}${refs(c.sources)}</div><div class="actions"><button class="primary" data-reveal>Revelar resposta</button></div></article><div class="flash-controls"><button data-prevcard>← Anterior</button><button data-remember="false">Rever depois</button><button data-remember="true">Lembrei ✓</button><button data-nextcard>Próximo →</button></div>`}
function glossary(){return `<p class="eyebrow">Vocabulário com contexto</p><h1>Glossário do acervo</h1><p class="lede">As definições respeitam os usos nas obras. Termos de RPG não equivalem a categorias clínicas.</p><div class="actions"><a class="button" href="#revisao">← Revisão ativa</a></div>${editorial.glossary.map(g=>`<details><summary>${esc(g.term)}</summary>${paras(g.definition)}${refs(g.sources)}</details>`).join('')}`}
function notebook(){return `<p class="eyebrow">Seu espaço de elaboração</p><h1>Meu caderno</h1><p class="lede">Guarde ideias, dúvidas e relações que você quer revisitar. Uma frase clara já é um registro útil.</p><div class="notice"><strong>${persistent?'Salvamento local disponível.':'Salvamento persistente indisponível neste navegador.'}</strong> ${persistent?'As notas ficam neste navegador e neste perfil; não são gravadas dentro do HTML. Para levar a outro dispositivo, exporte e depois importe.':'As notas ficam apenas nesta sessão. Use Exportar caderno para não perdê-las.'} A limpeza de dados do navegador pode apagar esse registro.</div><div class="editor"><label for="nextAction">Minha próxima ação pequena</label><input id="nextAction" placeholder="Ex.: comparar dignidade e mérito em duas obras" value="${esc(state.next)}"><br><br><label for="notes">Ideias, perguntas e anotações</label><textarea id="notes" placeholder="OBRA / TEMA:\n\nO que compreendi:\n\nO que ainda não sei:\n\nConexão com outra obra:\n\nPróximo passo:">${esc(state.notes)}</textarea><p class="status" id="saveStatus">${persistent?'Alterações são salvas neste navegador.':'Exporte para guardar suas notas.'}</p></div><div class="actions"><button class="primary" data-export>Exportar caderno e progresso</button><button data-import>Importar caderno</button><button data-downloadnotes>Salvar notas em texto</button><input type="file" id="importFile" accept="application/json,.json" hidden></div><div class="section-head"><h2>Três perguntas úteis</h2></div><div class="grid"><div class="card"><h3>O que o texto afirma?</h3><p>Registre a ideia e a obra. Evite misturar sua interpretação com a formulação original.</p></div><div class="card"><h3>O que eu entendi?</h3><p>Explique com um exemplo seu. Se não conseguir, indique exatamente onde apareceu a dúvida.</p></div><div class="card"><h3>O que preciso conferir?</h3><p>Identifique uma fonte, uma divergência entre versões ou uma afirmação que exige pesquisa.</p></div></div>`}
function edition(){return `<p class="eyebrow">Cobertura e leitura crítica</p><h1>Fontes e versões</h1><p class="lede">Uma edição de estudo do Arquivo.zip enviado, com textos completos, imagens incorporadas e sínteses identificadas.</p><div class="grid"><div class="card"><span class="num">COBERTURA</span><h3>33 de 33 arquivos</h3><p>26 Word, 3 PDFs, 2 Markdown e 2 figuras. Os 26 registros auxiliares do macOS foram desconsiderados porque não são obras.</p></div><div class="card"><span class="num">PRESERVAÇÃO</span><h3>Conteúdo e origem</h3><p>Textos, tabelas e ${editorial.imageCount} imagens únicas incorporadas (as figuras repetidas compartilham a mesma mídia). Os 3 PDFs originais também podem ser vistos ou salvos offline.</p></div><div class="card"><span class="num">ORGANIZAÇÃO</span><h3>Síntese e documento</h3><p>7 módulos explicativos, resumos por arquivo, conexões e revisão. A leitura guiada é uma elaboração nova; o texto integral mantém a formulação da fonte.</p></div></div><div class="notice"><strong>Limite da edição:</strong> o pacote não contém o histórico completo das conversas do projeto. A cobertura integral aqui se refere aos arquivos recebidos. Referências externas continuam identificadas, mas seus sites, áudios e vídeos não estão incorporados. Links externos precisam de internet.</div>
<div class="section-head"><h2>Comparar sem apagar versões</h2></div><div class="table-scroll compare"><table><thead><tr><th>Família</th><th>Relação entre os arquivos</th><th>Como estudar</th></tr></thead><tbody>${editorial.variants.map(v=>`<tr><td><strong>${esc(v.family)}</strong>${refs(v.ids)}</td><td>${esc(v.relation)}</td><td>${esc(v.guidance)}</td></tr>`).join('')}</tbody></table></div>
<div class="section-head"><h2>Diferenças que importam</h2></div><div class="module-body"><p>As fórmulas de Casas e os significados de IEC variam. Na família Manual Inter-AI/Mestre, aparecem pesos <strong>45/35/10/10</strong>; na Ficha Universal, <strong>70/20/10</strong>; outra versão integrada apresenta <strong>55/25/15/5</strong>. Também há modelos que separam Casa Funcional de Casa Narrativa. Esses números são regras internas dos documentos, não escores científicos validados.</p>${refs(['obra-02','obra-04','obra-05','obra-13','obra-27'])}<p>Na versão reconstruída, IEC aparece como <strong>Índice de Equilíbrio Covenant</strong>; em outros documentos, como índice de estilo cognitivo. Uma mesma sigla não garante o mesmo conceito. Há ainda títulos e rodapés com versões internas diferentes. Por isso, esta edição não calcula uma classificação única nem declara um arquivo definitivamente canônico.</p>${refs(['obra-26','obra-27'])}</div>
<div class="section-head"><h2>Notas de leitura factual</h2></div><details><summary>TDAH, dupla excepcionalidade e apoio de IA</summary><p>As generalizações da obra sobre um “cérebro 2e”, criatividade, desempenho e potencial devem ser lidas criticamente. Elas não demonstram um perfil individual. Mapas de RPG e autoavaliações do acervo não estabelecem diagnóstico.</p><p>Como referência clínica externa, a NICE recomenda diagnóstico de TDAH por profissional qualificado, com avaliação clínica e psicossocial completa; escalas isoladas não bastam. O NIMH descreve manifestações e estratégias de apoio que variam conforme as necessidades da pessoa. Essas referências sustentam esta nota editorial, não validam todas as afirmações do arquivo.</p><p><a href="https://www.nice.org.uk/guidance/ng87/chapter/recommendations" target="_blank" rel="noopener noreferrer">NICE NG87 · recomendações</a> · <a href="https://www.nimh.nih.gov/health/publications/attention-deficit-hyperactivity-disorder-what-you-need-to-know" target="_blank" rel="noopener noreferrer">NIMH · informações sobre TDAH</a>. Consulta: 10/09/2026.</p>${refs(['obra-33'])}</details><details><summary>Música, história e interpretação</summary><p>História de bandas, interpretação de letras e experiência emocional não são a mesma coisa. A biblioteca conserva atribuições e bibliografias das obras, mas esta edição não refez a pesquisa de cada afirmação histórica ou neurocientífica. A presença de uma referência no texto não comprova, por si só, que ela sustente a afirmação associada.</p>${refs(['obra-18','obra-22','obra-24','obra-31'])}</details><details><summary>Sociedades, mitologia e calendário</summary><p>Anonymous, Maçonaria, Illuminati, elfos e calendário religioso aparecem em camadas diferentes. As adaptações de Álfheim e Armagedom são ficcionais. Alegações sobre grupos reais e datas históricas permanecem como conteúdo atribuído às fontes. As datas de TEMI, eventos e efemérides do material de 2026 não foram revalidadas como agenda vigente.</p>${refs(['obra-01','obra-11','obra-12','obra-30'])}</details>
<div class="section-head"><h2>Inventário completo</h2></div><div class="table-scroll"><table><tr><th>ID</th><th>Arquivo recebido</th><th>Formato</th><th>Palavras extraídas</th></tr>${docs.map(d=>`<tr><td>${d.id.slice(-2)}</td><td class="break-word"><a href="#obra/${d.id}">${esc(d.name)}</a></td><td>${d.ext.slice(1).toUpperCase()}</td><td>${fmt(d.words)}</td></tr>`).join('')}</table></div><details><summary>Detalhes de incorporação</summary><p>Imagens foram deduplicadas por conteúdo e comprimidas sem perdas, com a resolução preservada. Todo o código e a mídia da leitura estão dentro deste arquivo. A biblioteca carrega uma obra por vez para manter a navegação responsiva.</p><p>A conversão Word–HTML preserva os textos e as tabelas, mas não reproduz a paginação original nem todas as convenções visuais do Word. Nos PDFs, a extração pode alterar a ordem de tabelas e caracteres; o PDF original incorporado permite conferir a página. As duas versões Markdown de Conurbação foram mantidas, inclusive sua pequena diferença textual.</p><p>Instruções e prompts que apareçam nos documentos são apresentados como conteúdo documental. Não são executados por esta página.</p><p>Recursos locais: busca, fonte ajustável, modo foco, tema escuro, progresso, cartões e caderno. O navegador pode limitar armazenamento ou visualização de PDF em arquivos locais; a opção de salvar o PDF e exportar o caderno oferece uma alternativa.</p></details><p class="fineprint">Curadoria e montagem: Aldenir Orquestrador Total, leitura de Word/PDF e análise paralela das famílias do acervo. Amazing Drawing disponível como tela de desenho na conversa; os mapas desta edição foram construídos diretamente no HTML. Não houve publicação em serviço externo.</p>`}
let galleryPage=0,galleryTheme='';const GALLERY_PAGE_SIZE=12;
function diagramSvg(d){return d.svg||''}
function visualModule(i){const list=(editorial.diagrams||[]).filter(d=>Number(d.moduleIndex)===Number(i)).slice(0,2);return list.length?`<div class="module-visuals no-print">${list.map(d=>`<figure class="diagram-wide"><button class="diagram-button" data-diagram="${esc(d.id)}" aria-label="Ampliar diagrama ${esc(d.title)}">${diagramSvg(d)}</button><figcaption><strong>${esc(d.title)}</strong> · ${esc(d.caption)} <button data-diagram="${esc(d.id)}">Ampliar ↗</button></figcaption></figure>`).join('')}</div>`:''}
function artworkStrip(){return (editorial.artworks||[]).length?`<section class="artwork-strip">${editorial.artworks.map(a=>`<figure><img data-asset="${a.asset}" alt="${esc(a.caption)}" loading="lazy"><figcaption><span class="eyebrow">ILUSTRAÇÃO NOVA · FICÇÃO</span><h3>${esc(a.title)}</h3><p>${esc(a.caption)}</p></figcaption></figure>`).join('')}</section>`:''}
function visualPage(){return `<p class="eyebrow">Aprender também pelo olhar</p><h1>Atlas visual</h1><p class="lede">${editorial.diagrams.length} diagramas novos, ${editorial.artworks.length} ilustrações temáticas e ${editorial.gallery.length} imagens únicas das fontes. Clique para ampliar e use os links para voltar à obra.</p><div class="visual-tabs actions"><a class="button primary" href="#diagramas-visuais" data-visual-scroll="diagramas-visuais">Mapas didáticos</a><a class="button" href="#ilustracoes-novas" data-visual-scroll="ilustracoes-novas">Ilustrações novas</a><a class="button" href="#galeria-fontes" data-visual-scroll="galeria-fontes">Galeria das fontes</a></div><div class="notice">Os diagramas são sínteses editoriais. As ilustrações novas representam metáforas literárias; não documentam acontecimentos reais. As imagens da galeria preservam o conteúdo visual das fontes.</div><section id="diagramas-visuais"><div class="section-head"><h2>Doze mapas para conectar ideias</h2><span class="small">Amplie para explorar os detalhes</span></div><div class="diagram-grid">${editorial.diagrams.map((d,i)=>`<article class="diagram-card"><button class="diagram-button" data-diagram="${esc(d.id)}" aria-label="Ampliar diagrama ${esc(d.title)}">${diagramSvg(d)}</button><div class="diagram-copy"><span class="eyebrow">FIGURA ${String(i+1).padStart(2,'0')} · SÍNTESE</span><h3>${esc(d.title)}</h3><p>${esc(d.caption)}</p>${refs(d.sources)}<button data-diagram="${esc(d.id)}">Ampliar figura ↗</button></div></article>`).join('')}</div></section><section id="ilustracoes-novas"><div class="section-head"><h2>Paisagens do imaginário</h2><span class="small">Criadas para esta edição</span></div>${artworkStrip()}</section><section id="galeria-fontes"><div class="section-head"><h2>Imagens presentes nas obras</h2></div><p class="small">Uma mesma imagem pode pertencer a mais de uma obra. A galeria reúne apenas uma cópia visual e conserva os links de origem.</p><div class="filters"><label><span class="sr-only">Tema da galeria</span><select id="galleryTheme"><option value="">Todos os temas</option>${[...new Set(docs.map(d=>d.theme))].sort().map(t=>`<option ${t===galleryTheme?'selected':''}>${esc(t)}</option>`).join('')}</select></label></div><div id="galleryCount" class="small" role="status"></div><div id="galleryGrid" class="gallery-grid"></div><div id="galleryPagination" class="actions no-print"></div></section>`}
function galleryRender(){const list=editorial.gallery.filter(g=>!galleryTheme||g.sources.some(id=>byId(id)?.theme===galleryTheme)),max=Math.max(1,Math.ceil(list.length/GALLERY_PAGE_SIZE));galleryPage=Math.max(0,Math.min(galleryPage,max-1));const slice=list.slice(galleryPage*GALLERY_PAGE_SIZE,(galleryPage+1)*GALLERY_PAGE_SIZE);$('#galleryCount').textContent=`${list.length} imagens · página ${galleryPage+1} de ${max}`;$('#galleryGrid').innerHTML=slice.map(g=>`<figure class="gallery-card"><button class="gallery-image" data-image="${g.asset}" aria-label="Ampliar ${esc(g.title)}"><img data-asset="${g.asset}" alt="${esc(g.title)}" loading="lazy"></button><figcaption><strong>${esc(g.title)}</strong>${refs(g.sources)}</figcaption></figure>`).join('');$('#galleryPagination').innerHTML=`<button data-gallery-prev ${galleryPage===0?'disabled':''}>← Imagens anteriores</button><button data-gallery-next ${galleryPage===max-1?'disabled':''}>Próximas imagens →</button>`;activateImages($('#galleryGrid'))}
function showDiagram(id){const d=editorial.diagrams.find(d=>d.id===id);if(!d)return;const url=URL.createObjectURL(new Blob([d.svg],{type:'image/svg+xml'}));$('#lightbox img').src=url;$('#lightbox img').alt=d.description||d.caption;$('#lightbox .dialogbar span').textContent=d.title;$('#lightbox').showModal();$('#lightbox').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.diagram)showDiagram(b.dataset.diagram);if(b.dataset.image){$('#lightbox img').src=assetURL(b.dataset.image);$('#lightbox img').alt=b.getAttribute('aria-label')||'Imagem ampliada';$('#lightbox .dialogbar span').textContent='Imagem preservada da fonte';$('#lightbox').showModal()}if(b.dataset.visualScroll){e.preventDefault();document.getElementById(b.dataset.visualScroll)?.scrollIntoView({behavior:motion()})}if(b.hasAttribute('data-gallery-next')){galleryPage++;galleryRender();$('#galeria-fontes').scrollIntoView({behavior:motion()})}if(b.hasAttribute('data-gallery-prev')){galleryPage--;galleryRender();$('#galeria-fontes').scrollIntoView({behavior:motion()})}});
document.addEventListener('change',e=>{if(e.target.id==='galleryTheme'){galleryTheme=e.target.value;galleryPage=0;galleryRender()}});
document.addEventListener('click',e=>{const im=e.target.closest('.artwork-strip img,.hero-art img');if(im){$('#lightbox img').src=im.src;$('#lightbox img').alt=im.alt;$('#lightbox .dialogbar span').textContent='Ilustração temática criada para esta edição';$('#lightbox').showModal()}});

function route(){const hash=location.hash.slice(1)||'inicio';if(hash.startsWith('obra-')&&document.getElementById(hash)){document.getElementById(hash).scrollIntoView();return}let [page,arg]=hash.split('/');currentBook=null;if(page==='obra')currentTab='integral';const renderers={inicio:home,mapa:mapPage,trilhas:trails,biblioteca:library,revisao:flashPage,caderno:notebook,edicao:edition,glossario:glossary,visuais:visualPage};$('#main').innerHTML=page==='obra'?docPage(arg):page==='modulo'?modulePage(arg):(renderers[page]||home)();$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===({obra:'biblioteca',modulo:'trilhas',glossario:'revisao'}[page]||page)));document.body.classList.remove('menu-open');$('#menuBtn').setAttribute('aria-expanded','false');if(page==='visuais'){galleryRender();activateImages($('#main'))}if(page==='inicio'&&editorial.artworks?.length){const art=editorial.artworks[0],box=$('.hero-art');box.classList.add('has-image');box.innerHTML=`<img data-asset="${art.asset}" alt="${esc(art.caption)}">`;activateImages(box)}if(page==='modulo')activateImages($('#main'));if(page==='biblioteca')renderResults();if(page==='mapa')connection(0);if(page==='obra')docContent();if(page==='revisao')flashRender();window.scrollTo(0,0);document.title=(page==='obra'?byId(arg)?.title:page==='modulo'?editorial.modules[arg]?.title:'Atlas de estudo')+' • Acervo pessoal';updateProgress()}
function download(data,name,type){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function pdfURL(id){if(!pdfURLs.has(id))pdfURLs.set(id,blobURL(pdfs[id],'application/pdf'));return pdfURLs.get(id)}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.close){$('#'+b.dataset.close).close();return}if(b.dataset.connect!==undefined)connection(+b.dataset.connect);if(b.dataset.tab){currentTab=b.dataset.tab;docContent()}if(b.dataset.heading){e.preventDefault();if(currentBook)history.pushState(null,'','#obra/'+currentBook+'/'+b.dataset.heading);document.getElementById(b.dataset.heading)?.scrollIntoView({behavior:motion()})}if(b.hasAttribute('data-done')){state.done[b.dataset.done]=!state.done[b.dataset.done];save();b.textContent=state.done[b.dataset.done]?'✓ Estudado':'Marcar como estudado';b.setAttribute('aria-pressed',String(!!state.done[b.dataset.done]));toast('Progresso atualizado')}if(b.hasAttribute('data-print')){activateImages($('#main'));window.print()}if(b.dataset.pdf){$('#pdfviewer iframe').src=pdfURL(b.dataset.pdf);$('#pdfviewer').showModal()}if(b.dataset.downloadpdf){const a=document.createElement('a');a.href=pdfURL(b.dataset.downloadpdf);a.download=byId(b.dataset.downloadpdf).name;a.click()}if(b.hasAttribute('data-resume')&&state.resume){const r={...state.resume};if(location.hash===`#obra/${r.id}`)route();else location.hash=`obra/${r.id}`;setTimeout(()=>window.scrollTo(0,r.y||0),300)}if(b.hasAttribute('data-reveal')){$('#flashAnswer').hidden=false;b.hidden=true}if(b.hasAttribute('data-nextcard')){state.card++;save();flashRender()}if(b.hasAttribute('data-prevcard')){state.card--;save();flashRender()}if(b.hasAttribute('data-shuffle')){state.card=Math.floor(Math.random()*editorial.flashcards.length);save();flashRender()}if(b.dataset.remember!==undefined){state.known[state.card]=b.dataset.remember==='true';state.card++;save();flashRender()}if(b.hasAttribute('data-review-reset')){state.card=0;state.known={};save();flashRender();toast('Revisão reiniciada')}if(b.hasAttribute('data-export')){download(JSON.stringify({format:'aldenir-atlas-estudo-v1',exportedAt:new Date().toISOString(),state},null,2),'meu-caderno-atlas.json','application/json');toast('Exportação do caderno preparada')}if(b.hasAttribute('data-import'))$('#importFile').click();if(b.hasAttribute('data-downloadnotes'))download('MINHA PRÓXIMA AÇÃO\n'+state.next+'\n\nMEU CADERNO\n'+state.notes,'meu-caderno-atlas.txt','text/plain;charset=utf-8');});
document.addEventListener('click',e=>{const img=e.target.closest('.reading img');if(img){$('#lightbox .dialogbar span').textContent='Ilustração preservada da fonte';$('#lightbox img').src=img.src;$('#lightbox img').alt=img.alt;$('#lightbox').showModal()}});
document.addEventListener('input',e=>{if(e.target.id==='notes'||e.target.id==='nextAction'){state[e.target.id==='notes'?'notes':'next']=e.target.value;save();$('#saveStatus').textContent=persistent?'Salvo neste navegador às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'Armazenamento indisponível. Exporte para guardar suas notas.'}});
document.addEventListener('change',async e=>{if(e.target.id==='themeFilter'){themeFilter=e.target.value;renderResults()}if(e.target.id==='importFile'&&e.target.files[0]){try{const f=e.target.files[0];if(f.size>5e6)throw Error('Arquivo maior que 5 MB');const p=JSON.parse(await f.text());if(p.format!=='aldenir-atlas-estudo-v1'||!p.state||typeof p.state.notes!=='string')throw Error('Formato de caderno incompatível');const previous=state.notes;state.notes=previous&&p.state.notes!==previous?previous+'\n\n── CADERNO IMPORTADO ──\n\n'+p.state.notes:p.state.notes;if(typeof p.state.next==='string'&&p.state.next)state.next=state.next?state.next+' | Importado: '+p.state.next:p.state.next;const incoming=validateState(p.state);state.done={...state.done,...incoming.done};state.known={...state.known,...incoming.known};state.card=incoming.card;state.font=incoming.font;state.dark=incoming.dark;if(incoming.resume)state.resume=incoming.resume;save();applyPrefs();route();e.target.value='';toast('Caderno importado; notas existentes preservadas')}catch(err){toast('Não foi possível importar: '+err.message)}}});
$('#globalSearch').addEventListener('input',e=>{query=e.target.value;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>{if(location.hash!=='#biblioteca')location.hash='biblioteca';else renderResults()},180)});document.addEventListener('click',e=>{if(e.target.closest('#clearSearch')){query='';themeFilter='';$('#globalSearch').value='';$('#themeFilter').value='';renderResults()}});
